<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{AdCampaign,AdSlot,Sponsor}; use Illuminate\Http\Request;
class AdsManagerController extends Controller { public function index(){return view('admin.ads',['campaigns'=>AdCampaign::with(['sponsor','slot'])->latest()->get(),'slots'=>AdSlot::orderBy('placement')->get(),'sponsors'=>Sponsor::where('is_active',true)->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['title'=>'required|string|max:150','ad_slot_id'=>'required|exists:ad_slots,id','sponsor_id'=>'nullable|exists:sponsors,id','image_url'=>'nullable|url|max:2048','target_url'=>'nullable|url|max:2048','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after_or_equal:starts_at']);$d['is_active']=true;AdCampaign::create($d);return back()->with('status','Campaign created');} public function toggle(AdCampaign $adCampaign){$adCampaign->update(['is_active'=>!$adCampaign->is_active]);return back();} }
